// TH18 v1.00a Stage 4 BossCard1 (spell 32) -> Boss2.
// Source: st04bs.ecl.txt:538-606 BossCard1, 608-696 BossCard1_at.
// Source t0 = card start; first ring helper spawn at source t90; helper emits at +61.
const TIME_LIMIT: int = 2822;   // 120 shell buffer + 2700 source timer + 2 alignment
const SOURCE_LIMIT: int = 2700; // source spell(32, 2700, 0, ...)

// th18.eclm etSprite type -> TH18 catalog rows (bullet-types.md).
const TH18_BIG_YIN_YANG_R: int = 1088; // source type 46, radius 28
const TH18_YIN_YANG_R: int = 1056;     // source type 44, radius 10
const TH18_YIN_YANG_L: int = 1072;     // source type 45, radius 10

// BossCard1_at source EX chain (all async=0 except BOUNCE):
//   ANIM a1 -> OFFSCREEN 600 -> INVULN 600 -> ANGLE_ACCEL(120, +0.005/f, sign*w)
//   -> VELTIME(a1, target speed, current angle) -> ACCEL(160, 0.01 toward pi/2)
//   -> BOUNCE(async1, count4, walls U+L+R).
// Birth animation is omitted (approved); its -4*velocity spawn retreat is kept via sh_dist(-6).
// 597 = 600 minus ANGLE_ACCEL/VELTIME/ACCEL finite-end OFFSCREEN reruns.
xformdef SPIN(angvel: angle, target: fx) {
    offscreen_keep(597);
    set_ang_vel(angvel);
    set_accel(0.005fx);
    wait(120);
    set_ang_vel(0bam);
    set_accel(0fx);
    set_speed(target);
    @160 set_gravity(0fx, 0.01fx); // source ACCEL s=1.5707964 literal, fixed vector down
    set_gravity(0fx, 0fx);
    bounce_arm(7, 3); // source walls 13 = U+L+R -> target L1+R2+U4; source count 4 capped by 2-bit field
}

// One source BossCard1_at burst. %RANDRAD samples stay at their source positions/count:
// r0 before wait(60), r1 after the Lunatic-only group, r2 after the 44 group.
async sub boss_at() {
    var r0: angle = (rand(65536) - 32768) as angle; // line 616 %D = %RANDRAD
    wait(60);                                        // line 617 wait(60)
    var c: int = 1;                                  // diffI($C, 1, 3, 3, 3)
    if global(GVAR_RANK) >= 1 { c = 3; }
    if global(GVAR_RANK) == 3 {
        // lines 619-642: Lunatic only, E=4 rings, sprite 46, colors 0..3, c=3.
        var b: int = 0;
        for i in 0..4 {
            sh_reset(0);
            sh_sprite(0, TH18_BIG_YIN_YANG_R, b);
            sh_ring(0, 1);                            // etAim(3) fixed ring
            sh_aim(0, 0);
            sh_count(0, c, 1);
            sh_angle(0, r0 + (((i * 65536) / 12) as angle), 0deg); // 2pi/4/3 per ring
            sh_speed(0, 1.5fx, 0fx);                  // etSpeed(1.5,1.0) with M=1
            sh_xform(0, SPIN(2deg, 2.1fx));
            sh_dist(0, -6fx);
            sh_fire(0);
            b = b + 1;
        }
    }
    var r1: angle = (rand(65536) - 32768) as angle; // line 645 %D = %RANDRAD
    for k in 0..7 {
        // lines 648-668: 7 rings, sprite 44, colors 1..7.
        sh_reset(0);
        sh_sprite(0, TH18_YIN_YANG_R, k + 1);
        sh_ring(0, 1);
        sh_aim(0, 0);
        sh_count(0, c, 1);
        sh_angle(0, r1 + (((k * 65536) / (7 * c)) as angle), 0deg); // 2pi/7/c per ring
        sh_speed(0, 1.5fx, 0fx);
        sh_xform(0, SPIN(2deg, 2.6fx));
        sh_dist(0, -6fx);
        sh_fire(0);
    }
    var r2: angle = (rand(65536) - 32768) as angle; // line 670 %D = %RANDRAD
    for m in 0..7 {
        // lines 671-694: emitter 1, sprite 45, colors 1..7, reversed spin and 1.6 target.
        sh_reset(1);
        sh_sprite(1, TH18_YIN_YANG_L, m + 1);
        sh_ring(1, 1);
        sh_aim(1, 0);
        sh_count(1, c, 1);
        sh_angle(1, r2 + (((m * 65536) / (7 * c)) as angle), 0deg);
        sh_speed(1, 1.5fx, 0fx);
        sh_xform(1, SPIN(-2deg, 1.6fx));
        sh_dist(1, -6fx);
        sh_fire(1);
    }
}

// moveLimit(0,128,120,64): final x [-60,60], y [96,160]; direction inner x +-30, y 112..144.
// moveRand(60,4,1.0): fixed direction, scalar speed 1-k/60, mode0 linear (movement.md).
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.0fx * ((60 - k) as fx) / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -60fx { nx = -60fx; }
    if nx > 60fx { nx = 60fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 0x405b90: pi * signed unit, then the x/y branch corrections.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -30fx {
        a = r / 3;
    } else if $self_x > 30fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, 0.05 rad ~ 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}

async sub pattern() {
    wait(120); // shell buffer; source t0 is after it
    set_self_int(2, $frame);
    set_self_int(1, $frame + SOURCE_LIMIT);
    set_self_int(0, 60);            // idle until the first moveRand
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT); // source t0 movePosTime, zero from (0,128)
    wait(90);                       // source +90 label; first async spawn
    loop {
        if $frame >= self_int(1) { return; }
        spawn boss_at();            // source @BossCard1_at() async at t90
        var w: int = 120;           // !E/!N/!LO 120
        if global(GVAR_RANK) == 2 { w = 90; } // !H 90
        card_wait(w);
        if $frame >= self_int(1) { return; }
        card_move_rand();           // source moveRand(60,4,1.0)
        card_wait(120);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48)
    set_hurtbox(20fx);  // source setHurtbox(40,40)
    spell_begin(0, 32, pattern, TIME_LIMIT, 0, 0, 0); // spell(32, 2700, 0, ...)
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Training shell: extra controller at (0,0) with body collision off; real boss keeps source judgement.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(0fx, 128fx, 20000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}
